def diff(a,b,p=''):
    if type(a)!=type(b): print('TYPE',p);return
    if isinstance(a,dict):
        for k in set(a)|set(b):
            if k not in a: print('ADDED',p+'/'+k)
            elif k not in b: print('REMOVED',p+'/'+k)
            else: diff(a[k],b[k],p+'/'+k)
    elif isinstance(a,list):
        if len(a)!=len(b): print('LEN',p,len(a),len(b))
        else:
            for i,(x,y) in enumerate(zip(a,b)): diff(x,y,p+'/'+str(i))
    elif a!=b: print('CHANGED',p,repr(a)[:40],'->',repr(b)[:40])
